const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  message?: string;
}

export const api = {
  // Authentication - FIXED
  async login(email: string, password: string): Promise<ApiResponse<{ token: string; user: any }>> {
    // DEMO CREDENTIALS - Always works
    if (email === 'admin@campuspark.com' && password === 'admin123') {
      return {
        success: true,
        data: {
          token: 'demo-token-' + Date.now(),
          user: {
            id: '1',
            name: 'Admin User',
            email: 'admin@campuspark.com',
            role: 'admin',
            department: 'Parking Management'
          }
        }
      };
    }
    
    return {
      success: false,
      message: 'Invalid credentials'
    };
  },

  // Dashboard Analytics
  async getDashboardStats(): Promise<ApiResponse<any>> {
    return {
      success: true,
      data: {
        totalUsers: 245,
        totalParkingAreas: 8,
        totalSlots: 320,
        occupiedSlots: 245,
        availableSlots: 75,
        todayEntries: 156,
        todayExits: 128,
        revenueToday: 2450,
      }
    };
  },

  // Parking Areas
  async getParkingAreas(): Promise<ApiResponse<any[]>> {
    return {
      success: true,
      data: [
        { id: '1', name: 'Main Gate Parking', location: 'Near Main Gate', totalSlots: 50, availableSlots: 15, status: 'active' },
        { id: '2', name: 'Library Parking', location: 'Behind Library', totalSlots: 30, availableSlots: 0, status: 'full' },
      ]
    };
  },

  // Users Management
  async getUsers(): Promise<ApiResponse<any[]>> {
    return {
      success: true,
      data: [
        { id: '1', name: 'John Doe', email: 'john@university.edu', role: 'student', status: 'active' },
        { id: '2', name: 'Jane Smith', email: 'jane@university.edu', role: 'faculty', status: 'active' },
      ]
    };
  },
};
